# Let me look at unique 3x3 patterns
import numpy as np

unique_patterns = {}
for r in range(12 - 3 + 1):
    for c in range(12 - 3 + 1):
        key = tuple(tuple(grid[r+i][c+j] for j in range(3)) for i in range(3))
        if key not in unique_patterns:
            unique_patterns[key] = []
        unique_patterns[key].append((r, c))

# Show patterns that appear more than once
print("Looking for repeated 3x3 patterns...")
for pattern, positions in sorted(unique_patterns.items()):
    if len(positions) >= 2:
        print(f"Pattern appears {len(positions)} times at: {positions}")
        pr = list(pattern)
        for row in pr:
            print(' '.join(f"{cell:3d}" for cell in row))
        print()

